CREATE TABLE whatsapp_messages (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, conversation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, direction VARCHAR(3) NOT NULL, type VARCHAR(32) NOT NULL, body TEXT NOT NULL, payload JSON NULL, wamid VARCHAR(255) NULL, status VARCHAR(16) NOT NULL, sender VARCHAR(16) NOT NULL, author_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, tokens INT NOT NULL DEFAULT 0, error TEXT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), status_at DATETIME(6) NULL, PRIMARY KEY (id), UNIQUE KEY whatsapp_messages_wamid_uq (wamid), KEY whatsapp_messages_thread_idx (conversation_id,created_at,id), CONSTRAINT whatsapp_messages_direction_ck CHECK (direction IN ('in','out')), CONSTRAINT whatsapp_messages_status_ck CHECK (status IN ('received','queued','sent','delivered','read','played','failed')), CONSTRAINT whatsapp_messages_sender_ck CHECK (sender IN ('customer','ai','agent','template','system')), CONSTRAINT whatsapp_messages_conversation_fk FOREIGN KEY (conversation_id,user_id) REFERENCES whatsapp_conversations(id,user_id) ON DELETE CASCADE, CONSTRAINT whatsapp_messages_author_fk FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE SET NULL, CONSTRAINT whatsapp_messages_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci